class TransactionalMap:
    def __init__(self, initial=None):
        self._data = dict(initial) if initial is not None else {}
        self._transaction_stack = []

    def _record(self, key):
        if self._transaction_stack:
            present = key in self._data
            value = self._data[key] if present else None
            self._transaction_stack[-1].append((present, value))

    def _restore(self, present, value):
        if present:
            self._data[key] = value
        else:
            self._data.pop(key, None)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def put(self, key, value):
        self._record(key)
        self._data[key] = value

    def delete(self, key):
        if key not in self._data:
            return

        self._record(key)
        del self._data[key]

    def begin(self):
        self._transaction_stack.append([])

    def commit(self):
        if not self._transaction_stack:
            raise RuntimeError("no active transaction")

        log = self._transaction_stack.pop()

        if self._transaction_stack:
            self._transaction_stack[-1].extend(log)

    def rollback(self):
        if not self._transaction_stack:
            raise RuntimeError("no active transaction")

        log = self._transaction_stack.pop()

        for present, value in reversed(log):
            self._restore(present, value)
