import fractions

_ALLOWED_DIGITS = frozenset("0123456789")
_ALLOWED_WHITESPACE = frozenset(" \t\n\r\v\f")
_ALLOWED_OPERATORS = frozenset("()*/+-")


def evaluate(expression: str) -> fractions.Fraction:
    """
    Evaluate an arithmetic expression string and return a fractions.Fraction.

    Allowed syntax:
      - unsigned decimal integer literals
      - ASCII whitespace
      - parentheses
      - binary operators: + - * /
      - unary plus/minus operators, including arbitrary consecutive signs

    Standard precedence and left associativity for binary operators are used.
    Invalid input raises ValueError; division by zero raises ZeroDivisionError.
    """
    if not isinstance(expression, str):
        raise ValueError("expression must be a string")

    tokens = _tokenize(expression)
    parser = _Parser(tokens)
    return parser.parse()


def _tokenize(expression: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    i = 0
    n = len(expression)

    while i < n:
        ch = expression[i]

        if ch in _ALLOWED_DIGITS:
            j = i
            while j < n and expression[j] in _ALLOWED_DIGITS:
                j += 1
            tokens.append(("NUMBER", expression[i:j]))
            i = j
            continue

        if ch in _ALLOWED_WHITESPACE:
            i += 1
            continue

        if ch in _ALLOWED_OPERATORS:
            tokens.append((ch, ch))
            i += 1
            continue

        raise ValueError(f"invalid character: {ch!r}")

    if not tokens:
        raise ValueError("empty expression")

    return tokens


class _Parser:
    def __init__(self, tokens: list[tuple[str, str]]) -> None:
        self._tokens = tokens
        self._pos = 0

    def parse(self) -> fractions.Fraction:
        value = self._parse_expression()
        if self._pos != len(self._tokens):
            raise ValueError("unexpected trailing token")
        return value

    def _current(self) -> str:
        return self._tokens[self._pos][0]

    def _consume(self, expected: str) -> None:
        if self._pos >= len(self._tokens) or self._current() != expected:
            raise ValueError(f"expected {expected!r}")
        self._pos += 1

    def _parse_expression(self) -> fractions.Fraction:
        return self._parse_additive()

    def _parse_additive(self) -> fractions.Fraction:
        left = self._parse_multiplicative()

        while self._pos < len(self._tokens) and self._current() in ("+", "-"):
            op = self._current()
            self._consume(op)
            right = self._parse_multiplicative()

            if op == "+":
                left = left + right
            else:
                left = left - right

        return left

    def _parse_multiplicative(self) -> fractions.Fraction:
        left = self._parse_factor()

        while self._pos < len(self._tokens) and self._current() in ("*", "/"):
            op = self._current()
            self._consume(op)
            right = self._parse_factor()

            if op == "*":
                left = left * right
            else:
                left = left / right

        return left

    def _parse_factor(self) -> fractions.Fraction:
        sign = 1
        while self._pos < len(self._tokens) and self._current() in ("+", "-"):
            if self._current() == "-":
                sign = -sign
            self._pos += 1

        if self._pos >= len(self._tokens):
            raise ValueError("missing operand")

        token_type = self._current()

        if token_type == "NUMBER":
            value = fractions.Fraction(int(self._tokens[self._pos][1]))
            self._pos += 1

        elif token_type == "(":
            self._consume("(")
            value = self._parse_expression()
            self._consume(")")

        else:
            raise ValueError("expected number or parentheses")

        return sign * value
