def strongly_connected_components(graph):
    nodes = set(graph.keys())
    for neighbors in graph.values():
        nodes.update(neighbors)

    if not nodes:
        return []

    adjacency = {
        node: list(set(graph.get(node, [])))
        for node in nodes
    }

    index = 0
    indices = {}
    lowlink = {}
    stack = []
    on_stack = set()
    components = []

    for start in nodes:
        if start in indices:
            continue

        indices[start] = lowlink[start] = index
        index += 1
        stack.append(start)
        on_stack.add(start)

        dfs_stack = [(start, iter(adjacency[start]))]

        while dfs_stack:
            node, neighbors = dfs_stack[-1]

            try:
                neighbor = next(neighbors)
            except StopIteration:
                dfs_stack.pop()

                if lowlink[node] == indices[node]:
                    component = []
                    while True:
                        popped = stack.pop()
                        on_stack.remove(popped)
                        component.append(popped)
                        if popped == node:
                            break
                    components.append(sorted(component))

                if dfs_stack:
                    parent = dfs_stack[-1][0]
                    if lowlink[node] < lowlink[parent]:
                        lowlink[parent] = lowlink[node]
                continue

            if neighbor not in indices:
                indices[neighbor] = lowlink[neighbor] = index
                index += 1
                stack.append(neighbor)
                on_stack.add(neighbor)
                dfs_stack.append((neighbor, iter(adjacency[neighbor])))
            elif neighbor in on_stack:
                if indices[neighbor] < lowlink[node]:
                    lowlink[node] = indices[neighbor]

    return sorted(components)
